\"}]},{\"section\":\"verse_text\",\"section_title\":\"Books.Verse.verse-text\",\"children\":[{\"type\":\"content.Record\",\"title\":\"verse_text\",\"id\":3585,\"bb\":3158,\"url_path\":\"/en/library/bg/12/17/b3158/\",\"body_value\":\"yo na hṛṣyati na dveṣṭi
