hunks/0b6f_zxj9ay~6.js\",\"/_next/static/chunks/143cg6c13uly6.js\",\"/_next/static/chunks/07vk.k35-e~ti.js\",\"/_next/static/chunks/0j6k6n9cniknh.js\",\"/_next/static/chunks/0.zxv9arc6a56.js\",\"/_next/static/chunks/00-zmo-3n1bt8.js\",\"/_next/static/chunks/0p4z5tusn0jt6.js\",\"/_next/static/chunks/01mcazkjru_is.js\"],\"default\"]\n6:[\"$\",\"$L22\",null,{\"pageId\":3589,\"activeView\":{\"name\":\"default\",\"activeViewSuffix\":\"\",\"language\":\"en\"},\"children\":\"$@23\"}]\n9:null\ne:[[\"$\",\"title\",\"0\",{\"children\":\"Bhagavad-gītā As It Is 12.18-19\"}],[\"$\",\"meta\",\"1\",{\"name\":\"description\",\"content\":\"Srila Prabhupada''s books online\"}],[\"$\",\"meta\",\"2\",{\"name\":\"application-name\",\"content\":\"Vedabase\"}],[\"$\",\"link\",\"3\",{\"rel\":\"author\",\"href\":\"https://vedabase.io\"}],[\"$\",\"meta\",\"4\",{\"name\":\"author\",\"content\":\"A.C. Bhaktivedanta Swami - Srila Prabhupada\"}],[\"$\",\"meta\",\"5\",{\"name\":\"keywords\",\"content\":\"Srila Prabhupada,Krsna,Krishna,bhakti,devotion\"}],[\"$\",\"meta\",\"6\",{\"name\":\"creator\",\"content\":\"Prahlad Nrsimha das\"}]]\n"])self.__next_f.push([1,"25:T60c,"])self.__next_f.push([1,"A devotee is always free from all bad association. Sometimes one is praised and sometimes one is defamed; that is the nature of human society. But a devotee is always transcendental to artificial fame and infamy, distress or happiness. He is very patient. He does not speak of anything but the topics about Kṛṣṇa; therefore he is called silent. Silent does not mean that one should not speak; silent means that one should not speak nonsense. One should speak only of essentials, and the most essential speech for the devotee is to speak for the sake of the Supreme Lord. A devotee is happy in all conditions; sometimes he may get very palatable foodstuffs, sometimes not, but he is satisfied. Nor does he care for any residential facility. He may sometimes live underneath a tree, and he may sometimes live in a very palatial building; he is attracted to neither. He is called fixed because he is fixed in his determination and knowledge. We may find some repetition in the descriptions of the qualifications of a devotee, but this is just to emphasize the fact that a devotee must acquire all these qualifications. Without good qualifications, one cannot be a pure devotee. Harāv abhaktasya kuto mahad-guṇāḥ: one who is not a devotee has no good qualification. One who wants to be recognized as a devotee should develop the good qualifications. Of course he does not extraneously endeavor to acquire these qualifications, but engagement in Kṛṣṇa consciousness and devotional service automatically helps him develop them."])self.__next_f.push([1,"23:[\"$\",\"div\",null,{\"className\":\"flex flex-col min-h-screen text-vb-normal-text\",\"children\":[[\"$\",\"$L1a\",null,{\"className\":\"w-full left-0 z-30 bg-vb-body/95\",\"children\":[\"$\",\"$L1b\",null,{\"mainMenu\":\"$L24\",\"page\":{\"id\":3589,\"meta\":{\"type\":\"books.Verse\",\"slug\":\"18-19\",\"show_in_menus\":false,\"seo_title\":\"\",\"search_description\":\"\",\"first_published_at\":null,\"alias_of\":null,\"locale\":\"en\"},\"title\":\"TEXTS 18-19\",\"advanced_view_url_path\":\"/en/library/bg/12/advanced-view/#bb3162\",\"language_menu\":[{\"display_name\":\"አማርኛ (Ethiopian)\",\"language_code\":\"am\",\"enabled\":false,\"url_path\":\"/am/\"},{\"display_name\":\"Български (Bulgarian)\",\"language_code\":\"bg\",\"enabled\":true,\"url_path\":\"/bg/library/bg/12/18-19/\"},{\"display_name\":\"Čeština (Czech)\",\"language_code\":\"cs\",\"enabled\":true,\"url_path\":\"/cs/library/bg/12/18-19/\"},{\"display_name\":\"Dansk (Danish)\",\"language_code\":\"da\",\"enabled\":true,\"url_path\":\"/da/library/bg/12/18-19/\"},{\"display_name\":\"Deutsch (German)\",\"language_code\":\"de\",\"enabled\":true,\"url_path\":\"/de/library/bg/12/18-19/\"},{\"display_name\":\"English\",\"language_code\":\"en\",\"enabled\":true,\"url_path\":\"/en/library/bg/12/