0b6f_zxj9ay~6.js\",\"/_next/static/chunks/143cg6c13uly6.js\",\"/_next/static/chunks/07vk.k35-e~ti.js\",\"/_next/static/chunks/0j6k6n9cniknh.js\",\"/_next/static/chunks/0.zxv9arc6a56.js\",\"/_next/static/chunks/00-zmo-3n1bt8.js\",\"/_next/static/chunks/0p4z5tusn0jt6.js\",\"/_next/static/chunks/01mcazkjru_is.js\"],\"default\"]\n6:[\"$\",\"$L22\",null,{\"pageId\":3596,\"activeView\":{\"name\":\"default\",\"activeViewSuffix\":\"\",\"language\":\"en\"},\"children\":\"$@23\"}]\n9:null\ne:[[\"$\",\"title\",\"0\",{\"children\":\"Bhagavad-gītā As It Is 12.20\"}],[\"$\",\"meta\",\"1\",{\"name\":\"description\",\"content\":\"Srila Prabhupada''s books online\"}],[\"$\",\"meta\",\"2\",{\"name\":\"application-name\",\"content\":\"Vedabase\"}],[\"$\",\"link\",\"3\",{\"rel\":\"author\",\"href\":\"https://vedabase.io\"}],[\"$\",\"meta\",\"4\",{\"name\":\"author\",\"content\":\"A.C. Bhaktivedanta Swami - Srila Prabhupada\"}],[\"$\",\"meta\",\"5\",{\"name\":\"keywords\",\"content\":\"Srila Prabhupada,Krsna,Krishna,bhakti,devotion\"}],[\"$\",\"meta\",\"6\",{\"name\":\"creator\",\"content\":\"Prahlad Nrsimha das\"}]]\n"])self.__next_f.push([1,"25:T90a,"])self.__next_f.push([1,"In this chapter, from verse 2 through the end – from mayy āveśya mano ye mām (“fixing the mind on Me”) through ye tu dharmāmṛtam idam (“this religion of eternal engagement”) – the Supreme Lord has explained the processes of transcendental service for approaching Him. Such processes are very dear to the Lord, and He accepts a person engaged in them. The question of who is better – one who is engaged in the path of impersonal Brahman or one who is engaged in the personal service of the Supreme Personality of Godhead – was raised by Arjuna, and the Lord replied to him so explicitly that there is no doubt that devotional service to the Personality of Godhead is the best of all processes of spiritual realization. In other words, in this chapter it is decided that through good association one develops attachment for pure devotional service and thereby accepts a bona fide spiritual master and from him begins to hear and chant and observe the regulative principles of devotional service with faith, attachment and devotion and thus becomes engaged in the transcendental service of the Lord. This path is recommended in this chapter; therefore there is no doubt that devotional service is the only absolute path for self-realization, for the attainment of the Supreme Personality of Godhead. The impersonal conception of the Supreme Absolute Truth, as described in this chapter, is recommended only up to the time one surrenders himself for self-realization. In other words, as long as one does not have the chance to associate with a pure devotee, the impersonal conception may be beneficial. In the impersonal conception of the Absolute Truth one works without fruitive result, meditates and cultivates knowledge to understand spirit and matter. This is necessary as long as one is not in the association of a pure devotee. Fortunately, if one develops directly a desire to engage in Kṛṣṇa consciousness in pure devotional service, he does not need to undergo step-by-step improvements in spiritual realization. Devotional service, as described in the middle six chapters of Bhagavad-gītā, is more congenial. One need not bother about materials to keep body and soul together, because by the grace of the Lord everything is carried out automatically."])self.__next_f.push([1,"23:[\"$\",\"div\",null,{\"className\":\"flex flex-col min-h-screen text-vb-normal-text\",\"children\":[[\"$\",\"$L1a\",null,{\"className\":\"w-full left-0 z-30 bg-vb-body/95\",\"children\":[\"$\",\"$L1b\",null,{\"mainMenu\":\"$L24\",\"page\":{\"id\":3596,\"meta\":{\"type\":\"books.Verse\",\"slug\":\"20\",\"show_in_menus\":false,\"seo_title\":\"\",\"search_description\":\"\",\"first_published_at\":null,\"alias_of\":null,\"locale\":\"en\"},\"title\":\"TEXT 20\",\"advanced_view_url_path\":\"/en/library/bg/12/advanced-view/#bb3168\",\"langu